/* Arrival UX retains source route topology. Preview conditions never masquerade as a live feed. */
let arrivalRoute='CM05',arrivalDirection=1,arrivalMode='preview',arrivalDate='2026-10-29',arrivalTime=510,arrivalAnchor=490,arrivalRain=false,arrivalCorridor=true,arrivalBus='408',arrivalBoard='dematagoda',arrivalExpanded=false,arrivalFollow=false,previewTicker=null,liveSnapshot={source:null,vehicles:[],receivedAt:null},feedStatus='not-connected';
const arrivals=MetroArrivals;
const etaClock=m=>{if(!Number.isFinite(m))return '-';let h=(Math.floor(m/60)%24+24)%24;return (h%12||12)+':'+String((Math.floor(m)%60+60)%60).padStart(2,'0')+' '+(h>=12?'PM':'AM')};
const arrTimeInput=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(Math.floor(m)%60).padStart(2,'0');
function reportMinutes(iso){let t=Date.parse(iso);if(!Number.isFinite(t))return null;let date=new Date(Date.now()+19800000).toISOString().slice(0,10);return (t-Date.parse(date+'T00:00:00+05:30'))/60000}
function localMinutes(iso){if(!Number.isFinite(Date.parse(iso)))return null;let parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Colombo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));return Number(parts.find(p=>p.type==='hour').value)*60+Number(parts.find(p=>p.type==='minute').value)}
function arrivalModel(){let route=nr(arrivalRoute),ids=arrivals.stopOrder(route,arrivalDirection),preview=arrivals.preview(route,{date:arrivalDate,time:arrivalTime,anchor:arrivalAnchor,direction:arrivalDirection,rain:arrivalRain,corridor:arrivalCorridor});if(!ids.includes(arrivalBoard))arrivalBoard=ids[Math.min(8,ids.length-1)];let vehicles=arrivalMode==='preview'?preview.vehicles:liveSnapshot.vehicles.filter(v=>v.routeId===arrivalRoute&&v.direction===arrivalDirection).map(v=>({...v,freshness:arrivals.freshness(v.observedAt),times:v.rawTimes.map(t=>({...t,scheduledArrival:reportMinutes(t.scheduledArrival),expectedArrival:reportMinutes(t.expectedArrival),expectedDeparture:reportMinutes(t.expectedDeparture),actualArrival:reportMinutes(t.actualArrival),actualDeparture:reportMinutes(t.actualDeparture)}))}));let bus=vehicles.find(v=>v.number===arrivalBus)||vehicles[0]||null;return {route,ids,preview,vehicles,bus,now:arrivalMode==='preview'?arrivalTime:localMinutes(new Date().toISOString())}}
function modeBadge(){return `<span class="arrival-data-badge ${arrivalMode==='preview'?'preview-mode':'live-mode'}">${arrivalMode==='preview'?'PREVIEW · NOT LIVE':feedStatus==='connected'?'REPORTED LIVE DATA':'LIVE FEED UNAVAILABLE'}</span>`}
function atBoard(v,m){return v.times.find(t=>t.stopId===arrivalBoard)}
function waitLabel(t,m){if(!t)return 'ETA unavailable';if(arrivalMode==='live'&&m.bus?.freshness!=='fresh')return 'ETA stale';return m.now>=t.expectedDeparture?'Already departed':m.now>=t.expectedArrival?'At your stop':Math.ceil(t.expectedArrival-m.now)+' min'}
function selectedBusSummary(m){if(m.bus&&!m.bus.demo&&m.bus.freshness==='expired')return 'Position expired. No current location available.';if(!m.bus)return 'Bus positions are unavailable';let p=m.bus.position;if(!p)return 'GPS received · route position unavailable';if(p.phase==='not-started')return 'Waiting to depart';if(p.phase==='completed')return 'Trip completed';if(p.phase==='at-stop')return 'At '+stopName(m.ids[p.index]);return 'Between '+stopName(m.ids[p.index])+' and '+stopName(m.ids[p.index+1])}
function focusArrivalRoute(id,dir=arrivalDirection){arrivalRoute=id;arrivalDirection=dir;arrivalBus='408';arrivalExpanded=false;let ids=arrivals.stopOrder(nr(id),dir);arrivalBoard=ids.includes(networkOrigin)?networkOrigin:ids[Math.min(8,ids.length-1)];render()}
function setArrivalMode(mode){arrivalMode=mode;stopPreviewTicker();if(mode==='live')refreshLiveTelemetry();render()}
function switchArrivalDirection(){arrivalDirection*=-1;arrivalExpanded=false;render()}
function arrivalHero(){let m=arrivalModel(),first=m.vehicles.filter(v=>arrivalMode==='preview'||v.freshness==='fresh').map(v=>({v,t:atBoard(v,m)})).filter(x=>x.t&&x.t.expectedDeparture>=m.now).sort((a,b)=>a.t.expectedArrival-b.t.expectedArrival)[0];return `<article class="journeycard arrival-hero"><div class="journeybody"><div class="between">${routeTag(arrivalRoute)}${modeBadge()}</div><div class="arrival-route-title"><h2>${safe(m.route.name.en)}</h2><button class="circle-control" onclick="switchArrivalDirection()" aria-label="Reverse arrival direction">⇄</button></div><p class="tiny">Towards ${safe(stopName(m.ids.at(-1)))}</p><label class="arrival-board-label" for="arrival-board">Your boarding stop</label><select id="arrival-board" class="arrival-board-select" onchange="arrivalBoard=this.value;render()">${m.ids.map(id=>`<option value="${id}" ${id===arrivalBoard?'selected':''}>${safe(stopName(id))}</option>`).join('')}</select><div class="next-arrival"><div><span class="eyebrow">${first?'NEXT AT YOUR STOP':'ARRIVAL STATUS'}</span><strong>${first?waitLabel(first.t,{...m,bus:first.v}):arrivalMode==='live'?'Feed unavailable':'No more preview buses'}</strong><span class="tiny">${first?'Bus #'+safe(first.v.number)+' · expected '+etaClock(first.t.expectedArrival):'Published route and stops remain available'}</span></div><div class="arrival-bus-badge">${ic('bus')}<b>${first?'#'+safe(first.v.number):'-'}</b></div></div>${first?`<div class="arrival-clock-pair"><span>Scheduled<b>${etaClock(first.t.scheduledArrival)}</b></span><span>Expected arrival<b>${etaClock(first.t.expectedArrival)}</b></span><span>Departure<b>${etaClock(first.t.expectedDeparture)}</b></span></div>`:''}<div class="arrival-hero-actions"><button class="primary" onclick="arrivalFollow=!arrivalFollow;render();toast(arrivalFollow?'Bus followed in this app. System notifications are not connected.':'Bus unfollowed.')">${ic(arrivalFollow?'check':'bell')}${arrivalFollow?'Following corridor':'Follow corridor'}</button><button class="secondary" onclick="openArrivalContext()">${ic('clock')}Journey context</button></div></div><div class="journeyfooter"><button onclick="openArrivalRoutePicker()">${ic('bus')}Change route</button><button onclick="openArrivalBus('${m.bus?.number||''}')">${ic('pin')}Bus position</button></div></article>`}
function factorIcon(kind){if(kind==='rain')return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 15a5 5 0 1 1 1-10 6 6 0 0 1 11 4 3 3 0 0 1 0 6H6m1 3-1 3m7-3-1 3m7-3-1 3"/></svg>`;if(kind==='traffic')return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="7" y="2" width="10" height="19" rx="4"/><circle cx="12" cy="7" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="17" r="1"/></svg>`;return ic('clock')}
function arrivalFactors(){let m=arrivalModel(),p=m.preview,c=p.context;return `<section class="section arrival-factors"><div class="sectionhead between"><h2>What may affect your ride</h2><button class="textbtn" onclick="explainArrivalFactors()">Details</button></div><div class="factor-grid"><button onclick="openArrivalContext()">${factorIcon('traffic')}<b>${arrivalMode==='live'?'Traffic unknown':c.peak&&arrivalCorridor?'Busy corridor':'Lighter demand'}</b><span>${arrivalMode==='live'?'No traffic feed':c.label}</span></button><button onclick="openArrivalContext()">${factorIcon('rain')}<b>${arrivalMode==='live'?'Weather unknown':arrivalRain?'Rain scenario':'No weather delay'}</b><span>${arrivalMode==='live'?'No weather feed':arrivalRain?'Wet-road allowance':'Preview assumption'}</span></button><button onclick="openArrivalContext()">${ic('clock')}<b>${arrivalMode==='live'?'Headway unknown':c.headway+' min'}</b><span>${arrivalMode==='live'?'No schedule feed':'Sample departure spacing'}</span></button></div>${arrivalMode==='preview'?`<div class="corridor-impact"><div><b>${c.label}${arrivalRain?' + rain':''}</b><span>${arrivalCorridor?'Commuter-demand assumptions enabled':'Demand delay disabled'} · ${p.affected.length} segments affected in this preview</span></div><strong>+${Math.round(p.traffic+p.weather)}<small> min / full route</small></strong></div>`:'<div class="access-note">Live conditions need timestamped operator, traffic and weather data. No outside-factor forecast is shown as fact.</div>'}</section>`}
function arrivalRouteStrip(){let m=arrivalModel(),spacing=84,width=Math.max(600,(m.ids.length-1)*spacing+70),visible=m.vehicles.filter(v=>v.position&&v.position.phase!=='not-started'&&v.position.phase!=='completed'&&(v.demo||v.freshness==='fresh'||v.freshness==='stale'));return `<section class="section"><div class="sectionhead between"><h2>Buses along your route</h2><button class="textbtn" onclick="openNetworkMap()">Network map</button></div><div class="route-strip-shell"><div class="strip-label">${arrivalMode==='preview'?'Simulated route positions':'Reported route positions'} · ${visible.length} buses shown</div><div class="route-strip-scroll"><div class="route-strip-canvas" style="width:${width}px"><div class="strip-spine" style="--route-color:${m.route.color}"></div>${m.ids.map((id,i)=>`<button class="strip-stop ${id===arrivalBoard?'boarding':''}" style="left:${35+i*spacing}px" onclick="openNetworkStop('${id}')"><i></i><span>${safe(stopName(id))}</span></button>`).join('')}${visible.map((v,i)=>`<button class="strip-bus ${v.number===m.bus?.number?'selected':''} ${v.freshness==='stale'?'stale':''}" style="left:${35+(v.position.index+v.position.fraction)*spacing}px;top:${i%2?25:4}px" onclick="openArrivalBus('${safe(v.number)}')" aria-label="Bus ${safe(v.number)} on ${v.routeId}, ${v.demo?'preview position':v.freshness+' reported position'}"><span class="strip-tooltip">#${safe(v.number)}${v.demo?' · demo':v.freshness==='stale'?' · stale':''}</span><span class="strip-bus-icon">${ic('bus')}</span></button>`).join('')}</div></div><p class="tiny" style="padding:0 14px 12px;margin:0">${arrivalMode==='preview'?'Bus numbers and positions are illustrative.':visible.length?'Tap a bus for its reporting time and GPS details.':'No position is invented when the feed or route matching is unavailable.'} Swipe the strip to follow the stops.</p></div></section>`}
function upcomingBusCards(){let m=arrivalModel();return `<section class="section"><div class="sectionhead between"><h2>Upcoming buses</h2><span class="arrival-mini-mode">${arrivalMode==='preview'?'Preview schedule':feedStatus==='connected'?'Reported data':'Not connected'}</span></div>${m.vehicles.length?m.vehicles.map(v=>{let t=atBoard(v,m);let value=t?waitLabel(t,{...m,bus:v}):'No ETA';return `<button class="upcoming-bus ${v.number===m.bus?.number?'selected':''}" onclick="arrivalBus='${safe(v.number)}';render()"><span class="upcoming-number">${ic('bus')}#${safe(v.number)}</span><span class="upcoming-info"><b>${v.demo?'Preview bus':'Reported bus'} · ${v.routeId}</b><small>${safe(v.crowding)} · ${v.demo?'Illustrative update':v.freshness+' GPS report'}</small><small>${t?'Arrival '+etaClock(t.expectedArrival)+' · departs '+etaClock(t.expectedDeparture):'Stop arrival data unavailable'}</small></span><strong>${value}</strong></button>`}).join(''):`<div class="card feed-empty"><h2>No live bus data connected</h2><p class="sub">Keep the published stop sequence, or use the preview to explore the arrival experience.</p><button class="secondary full" style="margin-top:15px" onclick="setArrivalMode('preview')">Explore preview buses</button><a href="https://lankametro.lk/en/smartmetro" target="_blank" rel="noopener noreferrer">Open official SmartMetro tracker ↗</a></div>`}</section>`}
function sequenceRows(m,all=false){let bus=m.bus,position=bus?.position,center=position?.index??0;let indices=m.ids.map((_,i)=>i);if(!all&&!arrivalExpanded&&indices.length>8)indices=[...new Set([Math.max(0,center-1),...indices.slice(center,center+5),indices.length-1])];return indices.map((index,k)=>{let id=m.ids[index],t=bus?.times.find(t=>t.stopId===id),fresh=bus?.demo||bus?.freshness==='fresh',status=t&&fresh?arrivals.status(t,m.now):'unavailable',gap=k>0&&index>indices[k-1]+1;let label=status==='departed'?'Departed':status==='at-stop'?'Bus is here':status==='upcoming'?'In '+Math.ceil(t.expectedArrival-m.now)+' min':'Time unavailable';return `${gap?'<div class="sequence-gap">More intermediate stops</div>':''}<div class="arrival-stop ${status} ${id===arrivalBoard?'your-stop':''}"><button class="arrival-stop-main" onclick="openNetworkStop('${id}')"><span class="sequence-dot">${status==='at-stop'?ic('bus'):''}</span><span><b>${safe(stopName(id))}</b><small>${id===arrivalBoard?'YOUR BOARDING STOP · ':''}${status==='departed'?'Departed '+etaClock(t.expectedDeparture):status==='at-stop'?'Arrived '+etaClock(t.expectedArrival)+' · departs '+etaClock(t.expectedDeparture):t&&fresh?'Arrival '+etaClock(t.expectedArrival)+' · departure '+etaClock(t.expectedDeparture):'Awaiting a current arrival report'}</small>${t&&fresh&&Number.isFinite(t.scheduledArrival)?`<small>Scheduled ${etaClock(t.scheduledArrival)}${Math.round(t.expectedArrival-t.scheduledArrival)>0?' · +'+Math.round(t.expectedArrival-t.scheduledArrival)+' min expected delay':''}</small>`:''}</span><em>${label}</em></button>${status==='at-stop'&&bus?`<div class="at-stop-detail"><span>${ic('bus')}Bus #${safe(bus.number)}</span><span>${ic('people')}${safe(bus.crowding)}</span><span>${ic('access')}Wheelchair space unverified</span></div>`:''}</div>`}).join('')}
function arrivalSequence(all=false){let m=arrivalModel();return `<section class="section"><div class="sectionhead between"><h2>Arrival & departure sequence</h2><button class="textbtn" onclick="arrivalExpanded=!arrivalExpanded;render()">${arrivalExpanded?'Show fewer':'All '+m.ids.length+' stops'}</button></div><div class="arrival-sequence"><div class="sequence-caption"><b>${m.bus?'Bus #'+safe(m.bus.number):'No bus selected'}</b><span>${arrivalMode==='preview'?'Preview · '+etaClock(m.now):'Reported arrival data'}</span></div><p class="tiny" style="padding:0 16px 13px;margin:0">${m.bus?safe(selectedBusSummary(m)):'The published stop order stays available without live timings.'}</p><div class="sequence-spine">${sequenceRows(m,all)}</div></div></section>`}
function arrivalControls(){let c=arrivals.context(arrivalDate,arrivalTime);return `<div class="arrival-controls"><div class="arrival-mode-switch" role="group" aria-label="Arrival data mode"><button class="${arrivalMode==='preview'?'active':''}" aria-pressed="${arrivalMode==='preview'}" onclick="setArrivalMode('preview')">Preview</button><button class="${arrivalMode==='live'?'active':''}" aria-pressed="${arrivalMode==='live'}" onclick="setArrivalMode('live')">Live data</button></div><button class="arrival-context-button" onclick="openArrivalContext()">${arrivalMode==='preview'?arrivalDate+' · '+etaClock(arrivalTime):'Feed status'} ${ic('arrow')}</button></div>`}
const networkHomeWithPublishedRoutes=home;
home=function(){let m=arrivalModel();return `<div class="homehero"><div class="between"><span class="eyebrow">YOUR EVERYDAY JOURNEY</span><button class="textbtn" onclick="openArrivalContext()">Journey context ${ic('arrow')}</button></div><h1>${profile?'Good day, '+profile+'.':'Your next bus, clearly.'}</h1><div class="hero-meta">Arrivals, route progress and connections together.</div></div>${arrivalHero()}${arrivalControls()}${arrivalFactors()}${arrivalRouteStrip()}${upcomingBusCards()}${arrivalSequence()}${networkActive?`<section class="section"><h2>Your connected journey</h2>${networkPlanCard(networkActive,true)}</section>`:''}<section class="section"><button class="quicksearch" onclick="planJourney()">${ic('search')}<span><b>Where would you like to go?</b><small>Plan across all seven published routes</small></span>${ic('arrow')}</button></section><section class="section"><div class="sectionhead between"><h2>Published routes</h2><button class="textbtn" onclick="setTab('routes')">Explore all</button></div>${routeDirectory()}</section><p class="bottomnote">Preview timings and conditions are illustrative. Published stop order is retained. Actual bus GPS and arrivals appear only when a feed provides them.</p>`};
const publishedSelectedRoutePanel=selectedRoutePanel;
selectedRoutePanel=function(){arrivalRoute=networkRoute;arrivalDirection=networkReverse?-1:1;let original=publishedSelectedRoutePanel();return original.replace('<section class="route-stop-list">',`${arrivalControls()}${arrivalFactors()}${arrivalRouteStrip()}${upcomingBusCards()}${arrivalSequence()}<details class="published-order-details"><summary>Published stop directory</summary><section class="route-stop-list">`).replace('</section>'+networkNotice(),'</section></details>'+networkNotice())};
const publishedOpenRoute=openNetworkRoute;openNetworkRoute=function(id){arrivalRoute=id;arrivalDirection=1;arrivalExpanded=false;publishedOpenRoute(id)};
const publishedSelectMapRoute=selectMapRoute;selectMapRoute=function(id){if(id!=='all'){arrivalRoute=id;arrivalBus='408'}publishedSelectMapRoute(id)};
function openArrivalRoutePicker(){modal('Choose your arrival corridor',`<p class="sub">The arrival sequence uses each route’s published stop order.</p>${network.data.routes.map(r=>`<button class="network-routecard" onclick="closeModal();focusArrivalRoute('${r.id}',1)">${routeTag(r.id)}<span><b>${safe(routeDisplayName(r))}</b><small>${r.orderedStops.length} source stop positions</small></span>${ic('arrow')}</button>`).join('')}`)}
function openArrivalContext(){let c=arrivals.context(arrivalDate,arrivalTime);modal('Journey context & outside factors',`<div class="between"><h2>Explore timing changes</h2>${modeBadge()}</div><p class="sub" style="margin-top:12px">Calendar, demand and weather can change a journey. These controls demonstrate those effects; they are not current observations.</p><div class="scenario-buttons"><button onclick="setArrivalScenario('peak')">Weekday peak</button><button onclick="setArrivalScenario('offpeak')">Weekday off-peak</button><button onclick="setArrivalScenario('weekend')">Weekend busy period</button></div><form onsubmit="event.preventDefault();applyArrivalContext()"><label for="arrival-date">Preview date · Sri Lanka time</label><input id="arrival-date" type="date" value="${arrivalDate}" required><label for="arrival-time">Preview clock</label><input id="arrival-time" type="time" value="${arrTimeInput(arrivalTime)}" required><label class="checkrow"><input type="checkbox" id="arrival-demand" ${arrivalCorridor?'checked':''}>Apply a busy commuter / shopping corridor scenario</label><label class="checkrow"><input type="checkbox" id="arrival-rain" ${arrivalRain?'checked':''}>Add a rain / wet-road scenario</label><button class="primary full" style="margin-top:20px">Apply preview context</button></form><div class="preview-playback"><button class="secondary" onclick="advanceArrivalPreview(3)">Advance 3 min</button><button class="secondary" onclick="toggleArrivalPlayback()">${previewTicker?'Pause':'Play'} preview</button></div><div class="access-note"><b>Live data status: ${feedStatus==='connected'?'a source has reported data':'no operator feed connected'}</b><br>Real bus locations need timestamped vehicle GPS plus route matching. Current traffic, rain and timetable feeds are not connected. We won’t label the preview as live.</div><button class="textbtn full" onclick="explainArrivalFactors()">How the timing breakdown works →</button>`)}
function applyArrivalContext(){let date=$('#arrival-date').value,time=$('#arrival-time').value;if(!date||!time)return;let [h,m]=time.split(':').map(Number);arrivalDate=date;arrivalTime=h*60+m;arrivalAnchor=arrivalTime-20;arrivalCorridor=$('#arrival-demand').checked;arrivalRain=$('#arrival-rain').checked;arrivalMode='preview';stopPreviewTicker();closeModal();render()}
function setArrivalScenario(v){arrivalDate=v==='weekend'?'2026-10-31':'2026-10-29';arrivalTime=v==='peak'?510:v==='offpeak'?780:660;arrivalAnchor=arrivalTime-20;arrivalMode='preview';stopPreviewTicker();closeModal();render()}
function advanceArrivalPreview(n){arrivalMode='preview';arrivalTime+=n;render();if($('.sheet'))openArrivalContext()}
function stopPreviewTicker(){if(previewTicker){clearInterval(previewTicker);previewTicker=null}}
function toggleArrivalPlayback(){if(previewTicker){stopPreviewTicker();toast('Preview paused.');closeModal();return}arrivalMode='preview';previewTicker=setInterval(()=>{if(document.hidden||$('.sheet'))return;arrivalTime+=.25;render()},3000);closeModal();toast('Playing a labelled preview: 15 simulated seconds every 3 seconds.')}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPreviewTicker()});
function explainArrivalFactors(){let m=arrivalModel(),p=m.preview;modal('Why the estimate changes',`<h2>${safe(m.route.name.en)}</h2><div class="estimate-breakdown"><div><span>Baseline full-route preview</span><b>${Math.round(p.baseline)} min</b></div><div><span>Commuter / shopping demand</span><b>+${Math.round(p.traffic)} min</b></div><div><span>Rain / wet-road allowance</span><b>+${Math.round(p.weather)} min</b></div><div class="total"><span>Full-route preview estimate</span><b>${Math.round(p.total)} min</b></div></div><p class="sub">${p.context.label}. This is a transparent scenario model, not a trained forecast or a live traffic observation.</p><div class="card section"><h2>Affected corridor stops</h2><p class="sub" style="margin-top:12px">${p.affected.length?p.affected.map(stopName).map(safe).join(' · '):'No additional delay is applied in this scenario.'}</p></div><p class="tiny">Preview assumptions: 1.7 min per route kilometre, equal segment weighting, 0.7 min dwell per stop; extra commuter demand near selected busy stops during sample peak windows. Weekend shopping and rain allowances are separate and are added once.</p><p class="tiny">Actual route segment speeds, traffic, floods, missed departures, boarding queues, road works and passenger demand need timestamped data. The app must show unknown when that evidence is missing.</p><button class="primary full" style="margin-top:20px" onclick="openArrivalContext()">Change preview factors</button>`)}
function openArrivalBus(number){let m=arrivalModel(),v=m.vehicles.find(x=>x.number===number);if(!v){modal('Live bus positions',`<h2>No live bus feed connected</h2><p class="sub" style="margin-top:15px">The published network is available. Actual vehicle locations, bus numbers, timestamps and stop predictions need a connected operator feed.</p><button class="primary full" style="margin-top:20px" onclick="setArrivalMode('preview');closeModal()">Explore labelled preview buses</button>`);return}arrivalBus=v.number;modal('Bus #'+v.number,`<div class="between">${routeTag(v.routeId)}${modeBadge()}</div><h2 style="font-size:25px;margin:20px 0 10px">Bus #${safe(v.number)} · towards ${safe(stopName(m.ids.at(-1)))}</h2><p class="sub">${safe(selectedBusSummary({...m,bus:v}))}</p><div class="bus-fact-grid"><div><span>Reported crowding</span><b>${safe(v.crowding)}</b></div><div><span>Seats available</span><b>${v.seats===null?'Unknown':v.seats}</b></div><div><span>Position source</span><b>${v.demo?'Preview simulation':safe(v.source)}</b></div><div><span>Last position report</span><b>${v.demo?'Not a GPS report':new Date(v.observedAt).toLocaleTimeString('en-GB',{timeZone:'Asia/Colombo'})+' · '+v.freshness}</b></div></div>${v.demo?'<div class="access-note">This bus number, position and capacity are illustrative. No real vehicle or driver identity is asserted.</div>':`<div class="gps-coordinates"><span>Reported bus GPS · not a stop pin</span><b>${v.latitude.toFixed(6)}, ${v.longitude.toFixed(6)}</b><a class="textbtn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${v.latitude},${v.longitude}">Open reported vehicle GPS ↗</a></div>${!v.position?'<div class="access-note">GPS was received, but no valid adjacent-stop route match was supplied. It is not placed on the schematic.</div>':''}`}<button class="primary full" style="margin-top:20px" onclick="closeModal();render();document.getElementById('arrival-sequence-anchor')?.scrollIntoView({behavior:'smooth'})">Follow this bus in the sequence</button><button class="textbtn full" onclick="openNetworkMap()">See buses on the route map →</button>`)}
function busMapMarkers(){let m=arrivalModel(),vehicles=arrivalMode==='preview'?m.vehicles:liveSnapshot.vehicles.map(v=>({...v,freshness:arrivals.freshness(v.observedAt)}));return vehicles.filter(v=>v.position&&v.position.phase!=='not-started'&&v.position.phase!=='completed'&&(v.demo||v.freshness==='fresh'||v.freshness==='stale')&&(networkRoute==='all'||v.routeId===networkRoute)).map((v,i)=>{let p=arrivals.pointOnRoute(nr(v.routeId),v.direction,v.position.index,v.position.fraction);if(!p)return '';let offset=i%2?66:41;return `<g class="telemetry-marker ${v.freshness==='stale'?'stale':''}" transform="translate(${p[0]} ${p[1]})" data-marker-x="${p[0]}" data-marker-y="${p[1]}" role="button" tabindex="0" aria-label="Bus ${safe(v.number)}, ${v.demo?'preview':v.freshness+' reported'} position on ${v.routeId}" onclick="event.stopPropagation();openMapBus('${safe(v.number)}','${v.routeId}')" onkeydown="if(event.key==='Enter'){openMapBus('${safe(v.number)}','${v.routeId}')}"><path d="M0 -${offset-1}V-15" stroke="#222" stroke-width="1.5"/><rect x="-39" y="-${offset+21}" width="78" height="24" rx="7" fill="#171719" stroke="white" stroke-width="1.5"/><text x="0" y="-${offset+5}" text-anchor="middle" fill="white" font-size="10" font-weight="700">#${safe(v.number)}${v.demo?' · DEMO':v.freshness==='stale'?' · OLD':''}</text><circle r="14" fill="white"/><rect x="-12" y="-12" width="24" height="24" rx="7" fill="#b51f2a"/><use href="#i-bus" x="-8" y="-8" width="16" height="16" stroke="white" fill="none" stroke-width="1.7"/></g>`}).join('')}
function openMapBus(number,routeId){arrivalRoute=routeId;let v=liveSnapshot.vehicles.find(v=>v.number===number&&v.routeId===routeId);if(arrivalMode==='live'&&v)arrivalDirection=v.direction;openArrivalBus(number)}
const sourceNetworkSvg=networkSvg;networkSvg=function(interactive=true){let svg=sourceNetworkSvg(interactive);return svg.replace('</g></svg>',busMapMarkers()+'</g></svg>')};
const markerObservers=[];
function sizeBusMarkers(stage){let group=stage.querySelector('.network-viewport'),ctm=group?.getScreenCTM();if(!ctm)return;let scale=Math.hypot(ctm.a,ctm.b);if(!scale)return;for(let marker of stage.querySelectorAll('.telemetry-marker'))marker.setAttribute('transform',`translate(${marker.dataset.markerX} ${marker.dataset.markerY}) scale(${1/scale})`)}
const publishedInstallDiagram=installDiagram;installDiagram=function(stage){publishedInstallDiagram(stage);for(let i=markerObservers.length-1;i>=0;i--)if(!document.contains(markerObservers[i].stage)){markerObservers[i].mutation.disconnect();markerObservers[i].resize?.disconnect();markerObservers.splice(i,1)}if(!stage)return;let group=stage.querySelector('.network-viewport');let mutation=new MutationObserver(()=>sizeBusMarkers(stage));mutation.observe(group,{attributes:true,attributeFilter:['transform']});let resize=typeof ResizeObserver!=='undefined'?new ResizeObserver(()=>sizeBusMarkers(stage)):null;resize?.observe(stage);markerObservers.push({stage,mutation,resize});requestAnimationFrame(()=>sizeBusMarkers(stage))};
const publishedRenderMap=renderMap;renderMap=function(){publishedRenderMap();let title=$('#maparea .network-map-title');if(title)title.insertAdjacentHTML('beforeend',`<div class="map-telemetry-label">${modeBadge()}<span>${arrivalMode==='preview'?'Route-coloured demo buses · both directions':feedStatus==='connected'?'Timestamped GPS reports · stale positions are dimmed':'No vehicle markers without a connected feed'}</span></div>`)};
const publishedOpenMap=openNetworkMap;openNetworkMap=function(){publishedOpenMap();let title=$('.sheet .network-map-title');if(title)title.insertAdjacentHTML('beforeend',`<div class="map-telemetry-label">${modeBadge()}</div>`)};
const publishedStopDetails=openNetworkStop;openNetworkStop=function(id){publishedStopDetails(id);let m=arrivalModel();if(m.ids.includes(id)){let body=$('.sheetcontent');body.insertAdjacentHTML('afterbegin',`<div class="stop-arrival-snapshot"><div class="between"><b>Arrivals at this stop</b>${modeBadge()}</div>${m.vehicles.map(v=>{let t=v.demo||v.freshness==='fresh'?v.times.find(t=>t.stopId===id):null;return `<div><span>Bus #${safe(v.number)}</span><b>${t?(m.now>=t.expectedDeparture?'Departed':m.now>=t.expectedArrival?'At stop':Math.ceil(t.expectedArrival-m.now)+' min'):'Unknown'}</b><small>${t?'Arrival '+etaClock(t.expectedArrival)+' · departure '+etaClock(t.expectedDeparture):'Awaiting arrival data'}</small></div>`}).join('')||'<p class="tiny">No current arrival reports.</p>'}</div>`)}};
let previousArrivalViewKey=null;const previousArrivalRender=render;render=function(){let key=arrivalRoute+'|'+arrivalDirection+'|'+networkRoute,mapView=$('#main-diagram')?._captureView?.(),stripLeft=$('.route-strip-scroll')?.scrollLeft||0;previousArrivalRender();let sequence=$('.arrival-sequence');if(sequence)sequence.id='arrival-sequence-anchor';if(previousArrivalViewKey===key){if(mapView)$('#main-diagram')?._restoreView?.(mapView);let strip=$('.route-strip-scroll');if(strip)strip.scrollLeft=stripLeft}previousArrivalViewKey=key;};
const previousFollowConnection=followNetworkConnection;followNetworkConnection=function(id){let p=networkChoices.find(x=>x.id===id);if(p){arrivalRoute=p.legs[0].routeId;arrivalDirection=p.legs[0].direction;arrivalBoard=p.from}previousFollowConnection(id)};
// A configured same-origin endpoint can supply genuine telemetry; no URL or credentials are invented.
async function refreshLiveTelemetry(){let endpoint=window.METRO_TELEMETRY_ENDPOINT;if(!endpoint){feedStatus='not-connected';return}try{let url=new URL(endpoint,location.origin);if(url.origin!==location.origin)throw Error('Telemetry must use the configured same-origin service.');let r=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error('Feed unavailable');ingestTelemetry(await r.json())}catch{feedStatus='unavailable';render()}}
function ingestTelemetry(data){liveSnapshot=arrivals.validateSnapshot(data,network);feedStatus='connected';render();return {accepted:liveSnapshot.vehicles.length}}
window.MetroTelemetry={ingest:ingestTelemetry,refresh:refreshLiveTelemetry};
setInterval(()=>{if(arrivalMode==='live'&&liveSnapshot.vehicles.length&&!document.hidden){render();if(window.METRO_TELEMETRY_ENDPOINT)refreshLiveTelemetry()}},15000);
render();
